<?php
if(!isset($db)){http_response_code(404);exit;}
function conciergeSetup(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS onb_concierge(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,trip_id INT NULL,category VARCHAR(40) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->exec("CREATE TABLE IF NOT EXISTS onb_concierge_messages(id INT AUTO_INCREMENT PRIMARY KEY,ticket_id INT NOT NULL,user_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ticket_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
function conciergeAction($action,$u,$admin){if(!$u)throw new RuntimeException('Sign in required.');conciergeSetup();$body=p('body');if($action==='concierge_new'){if($admin)throw new RuntimeException('Use a traveller account.');$cat=p('category');if(!in_array($cat,['Flights','Accommodation','Dietary needs','Visa questions','Accessibility','Itinerary','Other'],true)||!$body||strlen($body)>5000)throw new RuntimeException('Complete your request.');$trip=(int)p('trip_id');if($trip&&!q('SELECT id FROM travellers WHERE user_id=? AND trip_id=?',[$u['id'],$trip])->fetchColumn())throw new RuntimeException('Invalid journey.');q('INSERT INTO onb_concierge(user_id,trip_id,category,body) VALUES(?,?,?,?)',[$u['id'],$trip?:null,$cat,$body]);}else{$id=(int)p('id');$ticket=q('SELECT * FROM onb_concierge WHERE id=?',[$id])->fetch();if(!$ticket||(!$admin&&(int)$ticket['user_id']!==(int)$u['id']))throw new RuntimeException('Access denied.');if($action==='concierge_reply'){if(!$body||strlen($body)>5000||$ticket['status']==='closed')throw new RuntimeException('Invalid reply or closed request.');q('INSERT INTO onb_concierge_messages(ticket_id,user_id,body) VALUES(?,?,?)',[$id,$u['id'],$body]);}elseif($action==='concierge_status'&&$admin&&in_array(p('status'),['open','in progress','closed'],true)){q('UPDATE onb_concierge SET status=? WHERE id=?',[p('status'),$id]);}else throw new RuntimeException('Access denied.');}go('page=concierge');}
function conciergeView($u,$admin){if(!$u){echo '<h2>Sign in to access your concierge</h2><a href="?page=login">Sign in</a>';return;}conciergeSetup();?><div class="onb-dash"><div class="dash-hero"><span>YOUR JOURNEY / PERSONAL ASSISTANCE</span><h1>Boarding Concierge</h1><p>From the little details to the big questions, keep your travel requests together.</p></div><p>Human support inbox. Not an emergency service. Do not submit passport numbers, payment details or medical records.</p><?php if(!$admin):?><details><summary>Start a new request</summary><?php form('concierge_new');?><label>Category<select name="category"><?php foreach(['Flights','Accommodation','Dietary needs','Visa questions','Accessibility','Itinerary','Other'] as $c):?><option><?=h($c)?></option><?php endforeach;?></select></label><label>Journey<select name="trip_id"><option value="0">General question</option><?php foreach(q('SELECT t.id,t.title FROM trips t JOIN travellers v ON v.trip_id=t.id WHERE v.user_id=?',[$u['id']]) as $t):?><option value="<?=(int)$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php area('body','How can we help?');?><button>Send request</button></form></details><?php endif;?><h2><?=$admin?'Support inbox':'Your requests'?></h2><?php $rows=q('SELECT c.*,u.name,t.title FROM onb_concierge c JOIN users u ON u.id=c.user_id LEFT JOIN trips t ON t.id=c.trip_id'.($admin?'':' WHERE c.user_id=?').' ORDER BY c.id DESC',$admin?[]:[$u['id']])->fetchAll();if(!$rows)echo '<p>No requests yet.</p>';foreach($rows as $r):?><details><summary><?=h($r['category'].' · '.$r['status'].' · '.$r['name'])?></summary><p><?=h($r['title']??'General question')?></p><p><?=nl2br(h($r['body']))?></p><?php foreach(q('SELECT m.*,u.name,u.role FROM onb_concierge_messages m JOIN users u ON u.id=m.user_id WHERE ticket_id=? ORDER BY m.id',[$r['id']]) as $m):?><article><strong><?=h($m['role']==='admin'?'Boarding Concierge':$m['name'])?></strong><p><?=nl2br(h($m['body']))?></p><small><?=h($m['created_at'])?></small></article><?php endforeach;if($r['status']!=='closed'):form('concierge_reply');?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><?php area('body','Reply');?><button>Send reply</button></form><?php endif;if($admin):form('concierge_status');?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Status<select name="status"><?php foreach(['open','in progress','closed'] as $st):?><option <?=$st===$r['status']?'selected':''?>><?=h($st)?></option><?php endforeach;?></select></label><button>Update status</button></form><?php endif;?></details><?php endforeach;?></div><?php }
function analyticsView($admin){if(!$admin){http_response_code(403);echo '<h2>Access denied</h2>';return;}agentSetup();conciergeSetup();$days=(int)($_GET['days']??30);if(!in_array($days,[30,90,365],true))$days=30;$since=date('Y-m-d H:i:s',time()-$days*86400);$leads=q('SELECT COUNT(*) FROM enquiries WHERE created_at>=?',[$since])->fetchColumn();$agent=q("SELECT COUNT(*) total,COALESCE(SUM(stage='won'),0) won,COALESCE(SUM(CASE WHEN payout='approved' THEN commission ELSE 0 END),0) approved FROM onb_agent_leads WHERE created_at>=?",[$since])->fetch();?><div class="onb-dash"><div class="dash-hero"><span>MANAGEMENT / PERFORMANCE</span><h1>Business intelligence</h1><p>Understand your pipeline and plan your next departure.</p></div><nav class="dash-filters"><?php foreach([30,90,365] as $d):?><a href="?page=analytics&amp;days=<?=$d?>" class="<?=$d===$days?'selected':''?>"><?=$d?> days</a><?php endforeach;?></nav><div class="metrics"><?php foreach(['Direct enquiries'=>$leads,'Agent leads'=>$agent['total'],'Agent win rate'=>$agent['total']?round(100*$agent['won']/$agent['total'],1).'%':'—','Approved unpaid CAD'=>number_format((float)$agent['approved'],2),'Open concierge requests'=>q("SELECT COUNT(*) FROM onb_concierge WHERE status!='closed'")->fetchColumn()] as $k=>$v):?><article><span><?=h($k)?></span><strong><?=h($v)?></strong></article><?php endforeach;?></div><p>Lead metrics use creation date; concierge backlog is current. Agent wins are reported sales stages, not verified bookings.</p><h2>Agent performance</h2><div class="dash-table"><table><thead><tr><th>Agent</th><th>Leads</th><th>Won</th><th>Win rate</th></tr></thead><tbody><?php foreach(q("SELECT u.name,COUNT(*) n,SUM(l.stage='won') w FROM onb_agent_leads l JOIN users u ON u.id=l.agent_id WHERE l.created_at>=? GROUP BY u.id,u.name ORDER BY w DESC",[$since]) as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['n'])?></td><td><?=h($r['w'])?></td><td><?=round(100*$r['w']/$r['n'],1)?>%</td></tr><?php endforeach;?></tbody></table></div><h2>Departure economics</h2><p>Full-capacity estimates using internal price and entered total cost. Not actual revenue or profit; commissions and taxes may be additional.</p><div class="dash-table"><table><thead><tr><th>Journey</th><th>Capacity</th><th>Projected CAD</th><th>Entered cost CAD</th><th>Estimated surplus CAD</th></tr></thead><tbody><?php foreach(q('SELECT title,seats,price,cost FROM trips ORDER BY id DESC') as $t):?><tr><td><?=h($t['title'])?></td><td><?=h($t['seats'])?></td><td><?=number_format($t['seats']*$t['price'],2)?></td><td><?=number_format((float)$t['cost'],2)?></td><td><?=$t['cost']>0?number_format($t['seats']*$t['price']-$t['cost'],2):'Not entered'?></td></tr><?php endforeach;?></tbody></table></div><p><a href="operations.php">Manage itemized expenses and announcements</a></p></div><?php }
